INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('51c48150-bb5a-591b-be35-69ccfe0938f1', 'Barbados Corporate Governance Guideline', 'Corporate Governance Guideline, 2013', 'The Guideline sets out the Bank’s expectations in relation to the minimum standards for corporate governance practices by all licensees. It will form an integral part of the framework used by the Bank in assessing the effectiveness of corporate governance practices.', 'The Guideline sets out the Bank’s expectations in relation to the minimum standards for corporate governance practices by all licensees. It will form an integral part of the framework used by the Bank in assessing the effectiveness of corporate governance practices.', 'The Guideline sets out the Bank’s expectations in relation to the minimum standards for corporate governance practices by all licensees. It will form an integral part of the framework used by the Bank in assessing the effectiveness of corporate governance practices.', 'Barbados', 'governance', 'in_force', '2013-01-01'::date, 'Barbados', 'https://www.carrotsandsticks.org/policies/14_1', ARRAY['guidance_frameworks', 'other sustainability policy', 'barbados', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('03dcfcf2-ff82-5ab9-b157-2b49ba7c9c89', 'Belgium organization of the electricity market', 'Law on the organization of the electricity market', 'The Law on the organization of the electricity market in Belgium, established in 1999, defines roles like producers and distributors, promotes renewable energy sources, and sets guidelines for electricity transportation and distribution. It targets all electricity market stakeholders to regulate the industry effectively.', 'The Law on the organization of the electricity market in Belgium, established in 1999, defines roles like producers and distributors, promotes renewable energy sources, and sets guidelines for electricity transportation and distribution. It targets all electricity market stakeholders to regulate the industry effectively.', 'The Law on the organization of the electricity market in Belgium, established in 1999, defines roles like producers and distributors, promotes renewable energy sources, and sets guidelines for electricity transportation and distribution. It targets all electricity market stakeholders to regulate the industry effectively.', 'Belgium', 'climate', 'in_force', '2025-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_40', ARRAY['regulations', 'sdg7', 'sdg11', 'mandatory', 'belgium', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d55706c4-3392-5d05-a328-0a51d86d8d49', 'Belgium Law of 12 December', 'Law of 12 December', 'The Law of 12 December 2025 in Belgium amends Article 116 of the law from 2 December 2024 regarding the disclosure of sustainability information by certain companies and groups. It establishes mandatory reporting requirements for these entities, focusing on the timing of compliance with the reporting obligations. This law applies to specific companies and groups that are required to disclose sustainability information, ensuring transparency and accountability in their operations. The policy is mandatory for the specified entities.', 'The Law of 12 December 2025 in Belgium amends Article 116 of the law from 2 December 2024 regarding the disclosure of sustainability information by certain companies and groups. It establishes mandatory reporting requirements for these entities, focusing on the timing of compliance with the reporting obligations. This law applies to specific companies and groups that are required to disclose sustainability information, ensuring transparency and accountability in their operations. The policy is mandatory for the specified entities.', 'The Law of 12 December 2025 in Belgium amends Article 116 of the law from 2 December 2024 regarding the disclosure of sustainability information by certain companies and groups. It establishes mandatory reporting requirements for these entities, focusing on the timing of compliance with the reporting obligations. This law applies to specific companies and groups that are required to disclose sustainability information, ensuring transparency and accountability in their operations. The policy is mandatory for the specified entities.', 'Belgium', 'climate', 'in_force', '2025-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_42', ARRAY['regulations', 'mandatory', 'belgium', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e2b715fb-65da-54f6-9555-46c4940ad055', 'Belgium organization of federal climate policy', 'Act on the organization of federal climate policy', 'The Act on the organization of federal climate policy in Belgium, 2024, aims to govern climate actions. It outlines rules for governmental departments and organizational procedures for managing climate-related matters. The target audience includes federal agencies, officials, and stakeholders involved in climate policy implementation.', 'The Act on the organization of federal climate policy in Belgium, 2024, aims to govern climate actions. It outlines rules for governmental departments and organizational procedures for managing climate-related matters. The target audience includes federal agencies, officials, and stakeholders involved in climate policy implementation.', 'The Act on the organization of federal climate policy in Belgium, 2024, aims to govern climate actions. It outlines rules for governmental departments and organizational procedures for managing climate-related matters. The target audience includes federal agencies, officials, and stakeholders involved in climate policy implementation.', 'Belgium', 'climate', 'in_force', '2024-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_32', ARRAY['mandatory', 'belgium', 'sdg13', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
