INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8c7574b4-b9d3-5feb-ad61-4af449b46004', 'Belgium Publication in accordance with Articles 472 through 478', 'Publication in accordance with Articles 472 through 478 of the Programme Act of 24 December 2002, amended by Articles 4 through 8 of the Act containing various provisions of 20 July 2005 and Articles 117 and 118 of the Act of 5 May 2019.', 'The policy document outlines various legislative decrees and regulations in Belgium, including education, prison administration, discrimination, and sustainable development. It targets governmental bodies, communities, and individuals involved in law enforcement, education, and social services.', 'The policy document outlines various legislative decrees and regulations in Belgium, including education, prison administration, discrimination, and sustainable development. It targets governmental bodies, communities, and individuals involved in law enforcement, education, and social services.', 'The policy document outlines various legislative decrees and regulations in Belgium, including education, prison administration, discrimination, and sustainable development. It targets governmental bodies, communities, and individuals involved in law enforcement, education, and social services.', 'Belgium', 'social', 'in_force', '2024-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_38', ARRAY['sdg4', 'sdg10', 'regulations', 'mandatory', 'belgium']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1c3de4b4-47ba-5e87-8199-3590e7abac95', 'Belgium Publication in accordance with Articles 472 through 478', 'Publication in accordance with Articles 472 through 478 of the Programme Act of 24 December 2002, amended by Articles 4 through 8 of the Act containing various provisions of 20 July 2005 and Articles 117 and 118 of the Act of 5 May 2019.', 'The policy document from Belgium for 2024 outlines legal amendments and decrees in various sectors like justice, sustainable development, and education. It covers regulations for prisons, media education, discrimination, and financial support for school meals. The target audience includes government officials, educators, and those involved in legal and social welfare matters.', 'The policy document from Belgium for 2024 outlines legal amendments and decrees in various sectors like justice, sustainable development, and education. It covers regulations for prisons, media education, discrimination, and financial support for school meals. The target audience includes government officials, educators, and those involved in legal and social welfare matters.', 'The policy document from Belgium for 2024 outlines legal amendments and decrees in various sectors like justice, sustainable development, and education. It covers regulations for prisons, media education, discrimination, and financial support for school meals. The target audience includes government officials, educators, and those involved in legal and social welfare matters.', 'Belgium', 'climate', 'in_force', '2024-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_39', ARRAY['sdg4', 'sdg10', 'regulations', 'mandatory', 'belgium', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2d48ead1-c931-5edb-963c-60a99846e40d', 'Belgium disclosure of sustainability information', 'Law on the disclosure of sustainability information', 'The Law on the Disclosure of Sustainability Information in Belgium mandates certain companies and groups to publish sustainability information and ensures the reliability of this information. This law transposes EU directives aimed at enhancing corporate transparency regarding sustainability practices. It applies to specific companies based on their annual net revenue and is designed to improve accountability in sustainability reporting. The requirements are mandatory for the entities covered under this legislation.', 'The Law on the Disclosure of Sustainability Information in Belgium mandates certain companies and groups to publish sustainability information and ensures the reliability of this information. This law transposes EU directives aimed at enhancing corporate transparency regarding sustainability practices. It applies to specific companies based on their annual net revenue and is designed to improve accountability in sustainability reporting. The requirements are mandatory for the entities covered under this legislation.', 'The Law on the Disclosure of Sustainability Information in Belgium mandates certain companies and groups to publish sustainability information and ensures the reliability of this information. This law transposes EU directives aimed at enhancing corporate transparency regarding sustainability practices. It applies to specific companies based on their annual net revenue and is designed to improve accountability in sustainability reporting. The requirements are mandatory for the entities covered under this legislation.', 'Belgium', 'climate', 'in_force', '2024-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_41', ARRAY['regulations', 'mandatory', 'belgium', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('354d6fae-708e-51ec-906b-dcd09932ffbc', 'Belgium Law proposition establishing a duty of vigilance', 'Law proposition establishing a duty of vigilance and a duty of responsibility for companies throughout their value chains', 'This law aims to establish a duty of care and responsibility for companies throughout their value chains. The proposed law requires companies to conduct due diligence on their supply chains to identify and address potential adverse impacts on human rights, the environment, and other areas. Companies would also be required to establish a grievance mechanism to address complaints related to their activities and to provide for remediation where necessary. Additionally, the proposed law provides for penalties for non-compliance, including fines and suspension or revocation of business licenses. The proposed law is intended to promote responsible business conduct and to ensure that companies are held accountable for their impacts on people and the environment throughout their value chains.', 'This law aims to establish a duty of care and responsibility for companies throughout their value chains. The proposed law requires companies to conduct due diligence on their supply chains to identify and address potential adverse impacts on human rights, the environment, and other areas. Companies would also be required to establish a grievance mechanism to address complaints related to their activities and to provide for remediation where necessary. Additionally, the proposed law provides for penalties for non-compliance, including fines and suspension or revocation of business licenses. The proposed law is intended to promote responsible business conduct and to ensure that companies are held accountable for their impacts on people and the environment throughout their value chains.', 'This law aims to establish a duty of care and responsibility for companies throughout their value chains. The proposed law requires companies to conduct due diligence on their supply chains to identify and address potential adverse impacts on human rights, the environment, and other areas. Companies would also be required to establish a grievance mechanism to address complaints related to their activities and to provide for remediation where necessary. Additionally, the proposed law provides for penalties for non-compliance, including fines and suspension or revocation of business licenses. The proposed law is intended to promote responsible business conduct and to ensure that companies are held accountable for their impacts on people and the environment throughout their value chains.', 'Belgium', 'climate', 'in_force', '2021-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_31', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'belgium', 'sdg16', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2b938f8c-3fb0-5489-a143-c52e7ac171aa', 'Belgium Financial Services and Markets Authority (FSMA) ESG Guidelines', 'Financial Services and Markets Authority (FSMA) ESG Guidelines', 'The Sustainable Finance Disclosure Regulation (SFDR), enacted by the European Union, aims to enhance transparency regarding sustainability risks and impacts within the financial sector. The regulation requires financial institutions and asset managers to disclose information about how they integrate environmental, social, and governance (ESG) factors into their investment processes. Specifically, firms must provide clear details on the sustainability risks they consider, the impacts of their investment decisions on sustainability factors, and how they incorporate these factors into their remuneration policies. The regulation also mandates transparency in marketing materials to avoid "greenwashing." It applies to financial products and services, including collective portfolio management and investment advisory services. The SFDR is part of the EU''s broader strategy to channel investments towards sustainable activities.', 'The Sustainable Finance Disclosure Regulation (SFDR), enacted by the European Union, aims to enhance transparency regarding sustainability risks and impacts within the financial sector. The regulation requires financial institutions and asset managers to disclose information about how they integrate environmental, social, and governance (ESG) factors into their investment processes. Specifically, firms must provide clear details on the sustainability risks they consider, the impacts of their investment decisions on sustainability factors, and how they incorporate these factors into their remuneration policies. The regulation also mandates transparency in marketing materials to avoid "greenwashing." It applies to financial products and services, including collective portfolio management and investment advisory services. The SFDR is part of the EU''s broader strategy to channel investments towards sustainable activities.', 'The Sustainable Finance Disclosure Regulation (SFDR), enacted by the European Union, aims to enhance transparency regarding sustainability risks and impacts within the financial sector. The regulation requires financial institutions and asset managers to disclose information about how they integrate environmental, social, and governance (ESG) factors into their investment processes. Specifically, firms must provide clear details on the sustainability risks they consider, the impacts of their investment decisions on sustainability factors, and how they incorporate these factors into their remuneration policies. The regulation also mandates transparency in marketing materials to avoid "greenwashing." It applies to financial products and services, including collective portfolio management and investment advisory services. The SFDR is part of the EU''s broader strategy to channel investments towards sustainable activities.', 'Belgium', 'climate', 'in_force', '2021-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_5', ARRAY['guidance_frameworks', 'other sustainability policy', 'belgium', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a49ee147-4b58-5a27-a601-78f6fc0f271c', 'Belgium 2020 Belgian Code on Corporate Governance', 'The 2020 Belgian Code on Corporate Governance', 'This is the third Belgian Code on Corporate Governance, which replaces the versions previously published in 2004 and 2009. The 2020 Code was necessary because of significant changes in the Belgian and European regulatory framework, as well as changes in societal and academic debates on the sound management of listed companies. The new Code emphasizes sustainable value creation and focuses on the long term. It provides guidance on diversity, talent development, and succession planning. The 2020 Code is based on principles rather than on detailed guidelines and rules, and compliance with its provisions is subject to the ''comply or explain'' principle. The article concludes by stating that governance is about people, and the new 2020 Code provides a basis for anyone involved in governance to create a sustainable future for their organization.', 'This is the third Belgian Code on Corporate Governance, which replaces the versions previously published in 2004 and 2009. The 2020 Code was necessary because of significant changes in the Belgian and European regulatory framework, as well as changes in societal and academic debates on the sound management of listed companies. The new Code emphasizes sustainable value creation and focuses on the long term. It provides guidance on diversity, talent development, and succession planning. The 2020 Code is based on principles rather than on detailed guidelines and rules, and compliance with its provisions is subject to the ''comply or explain'' principle. The article concludes by stating that governance is about people, and the new 2020 Code provides a basis for anyone involved in governance to create a sustainable future for their organization.', 'This is the third Belgian Code on Corporate Governance, which replaces the versions previously published in 2004 and 2009. The 2020 Code was necessary because of significant changes in the Belgian and European regulatory framework, as well as changes in societal and academic debates on the sound management of listed companies. The new Code emphasizes sustainable value creation and focuses on the long term. It provides guidance on diversity, talent development, and succession planning. The 2020 Code is based on principles rather than on detailed guidelines and rules, and compliance with its provisions is subject to the ''comply or explain'' principle. The article concludes by stating that governance is about people, and the new 2020 Code provides a basis for anyone involved in governance to create a sustainable future for their organization.', 'Belgium', 'governance', 'in_force', '2020-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_30', ARRAY['mandatory', 'belgium', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f64415d1-c38e-559b-ae8e-753f8bf3e0dc', 'Belgium Publication in accordance with Articles 472 through 478', 'Publication in accordance with Articles 472 through 478 of the Programme Act of 24 December 2002, amended by Articles 4 through 8 of the Act containing various provisions of 20 July 2005.', 'The document pertains to publications in compliance with specific articles of Belgian law, listing various legislative acts from different federal government departments. It details laws, decrees, and ordinances related to foreign affairs, internal affairs, social security, justice, and economic matters. Targeted at legal professionals and the public for transparency.', 'The document pertains to publications in compliance with specific articles of Belgian law, listing various legislative acts from different federal government departments. It details laws, decrees, and ordinances related to foreign affairs, internal affairs, social security, justice, and economic matters. Targeted at legal professionals and the public for transparency.', 'The document pertains to publications in compliance with specific articles of Belgian law, listing various legislative acts from different federal government departments. It details laws, decrees, and ordinances related to foreign affairs, internal affairs, social security, justice, and economic matters. Targeted at legal professionals and the public for transparency.', 'Belgium', 'governance', 'in_force', '2020-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_35', ARRAY['sdg16', 'mandatory', 'belgium', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7da7ea8b-a55e-54a7-9b02-3c817fc39661', 'Belgium’s National Energy and Climate Plan (NECP)', 'Belgium’s National Energy and Climate Plan (NECP)', 'The Belgian Integrated National Energy and Climate Plan (NECP) 2021-2030 outlines the country’s strategy to reduce greenhouse gas emissions, increase the use of renewable energy, improve energy efficiency, and ensure energy security in line with the European Green Deal and the EU''s 2030 climate and energy goals. Belgium sets ambitious targets to reduce emissions by 35% in non-ETS sectors and aims for 17.5% of energy consumption from renewable sources by 2030. The plan includes measures across various sectors such as energy, transport, industry, and residential buildings, as well as efforts to address energy security, affordability, and innovation. It highlights the importance of federal-regional collaboration to implement these measures and achieve set goals.', 'The Belgian Integrated National Energy and Climate Plan (NECP) 2021-2030 outlines the country’s strategy to reduce greenhouse gas emissions, increase the use of renewable energy, improve energy efficiency, and ensure energy security in line with the European Green Deal and the EU''s 2030 climate and energy goals. Belgium sets ambitious targets to reduce emissions by 35% in non-ETS sectors and aims for 17.5% of energy consumption from renewable sources by 2030. The plan includes measures across various sectors such as energy, transport, industry, and residential buildings, as well as efforts to address energy security, affordability, and innovation. It highlights the importance of federal-regional collaboration to implement these measures and achieve set goals.', 'The Belgian Integrated National Energy and Climate Plan (NECP) 2021-2030 outlines the country’s strategy to reduce greenhouse gas emissions, increase the use of renewable energy, improve energy efficiency, and ensure energy security in line with the European Green Deal and the EU''s 2030 climate and energy goals. Belgium sets ambitious targets to reduce emissions by 35% in non-ETS sectors and aims for 17.5% of energy consumption from renewable sources by 2030. The plan includes measures across various sectors such as energy, transport, industry, and residential buildings, as well as efforts to address energy security, affordability, and innovation. It highlights the importance of federal-regional collaboration to implement these measures and achieve set goals.', 'Belgium', 'climate', 'in_force', '2020-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_4', ARRAY['sdg13', 'sdg7', 'mandatory', 'belgium', 'sdg16', 'mandatory_regulations', 'sdg15', 'disclosure', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e8bdc5c0-9f99-5208-a224-4389d564512c', 'Belgium Belgian Corporate Governance Code', 'Belgian Corporate Governance Code', 'The 2020 Belgian Code on Corporate Governance provides a set of principles and provisions aimed at ensuring effective governance of listed companies in Belgium. It emphasizes the importance of sustainable value creation, transparency, and responsibility at all levels of corporate leadership. The code introduces specific principles regarding the structure and functioning of the board of directors, the role of executive management, and the fair treatment of shareholders. Key changes in this version include a focus on long-term value creation, diversity in leadership, and the promotion of responsible behavior. The Code requires companies to publicly disclose how they comply with its principles and provide clear explanations when they deviate from its provisions. A critical aspect of the Code is the emphasis on independence, accountability, and the role of specialized committees in assisting the board with decision-making.', 'The 2020 Belgian Code on Corporate Governance provides a set of principles and provisions aimed at ensuring effective governance of listed companies in Belgium. It emphasizes the importance of sustainable value creation, transparency, and responsibility at all levels of corporate leadership. The code introduces specific principles regarding the structure and functioning of the board of directors, the role of executive management, and the fair treatment of shareholders. Key changes in this version include a focus on long-term value creation, diversity in leadership, and the promotion of responsible behavior. The Code requires companies to publicly disclose how they comply with its principles and provide clear explanations when they deviate from its provisions. A critical aspect of the Code is the emphasis on independence, accountability, and the role of specialized committees in assisting the board with decision-making.', 'The 2020 Belgian Code on Corporate Governance provides a set of principles and provisions aimed at ensuring effective governance of listed companies in Belgium. It emphasizes the importance of sustainable value creation, transparency, and responsibility at all levels of corporate leadership. The code introduces specific principles regarding the structure and functioning of the board of directors, the role of executive management, and the fair treatment of shareholders. Key changes in this version include a focus on long-term value creation, diversity in leadership, and the promotion of responsible behavior. The Code requires companies to publicly disclose how they comply with its principles and provide clear explanations when they deviate from its provisions. A critical aspect of the Code is the emphasis on independence, accountability, and the role of specialized committees in assisting the board with decision-making.', 'Belgium', 'climate', 'in_force', '2020-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_7', ARRAY['guidance_frameworks', 'sdg7', 'mandatory', 'belgium', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ffccae80-5c70-523f-bf9d-86f18b5d424f', 'Belgium Guidelines to Issuers for ESG Reporting', 'Guidelines to Issuers for ESG Reporting, 2020', 'This ESG guidance has been created to help Euronext listed companies in their interactions with investors and the wider ESG community, to help them understand how to address ESG issues as a key component of investor relations, as well as the main principles to consider when preparing an ESG report.', 'This ESG guidance has been created to help Euronext listed companies in their interactions with investors and the wider ESG community, to help them understand how to address ESG issues as a key component of investor relations, as well as the main principles to consider when preparing an ESG report.', 'This ESG guidance has been created to help Euronext listed companies in their interactions with investors and the wider ESG community, to help them understand how to address ESG issues as a key component of investor relations, as well as the main principles to consider when preparing an ESG report.', 'Belgium', 'climate', 'in_force', '2020-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_8', ARRAY['guidance_frameworks', 'sdg11', 'belgium', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dedb920d-4e48-5a32-b95a-e2d6f8f06fcc', 'Belgium National Business and Human Rights Action Plan', 'National Business and Human Rights Action Plan', 'This plan provides an opportunity to reaffirm Belgium''s support for a number of commitments made in other forums and which overlap with the same principles, such as the Guiding Principles for Multinationals (revised in 2011) of the Organization for Economic Cooperation and Development (OECD) or a series of commitments made at the level of the International Labor Organization (ILO).', 'This plan provides an opportunity to reaffirm Belgium''s support for a number of commitments made in other forums and which overlap with the same principles, such as the Guiding Principles for Multinationals (revised in 2011) of the Organization for Economic Cooperation and Development (OECD) or a series of commitments made at the level of the International Labor Organization (ILO).', 'This plan provides an opportunity to reaffirm Belgium''s support for a number of commitments made in other forums and which overlap with the same principles, such as the Guiding Principles for Multinationals (revised in 2011) of the Organization for Economic Cooperation and Development (OECD) or a series of commitments made at the level of the International Labor Organization (ILO).', 'Belgium', 'climate', 'in_force', '2017-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_16', ARRAY['sdg8', 'other sustainability policy', 'regulations', 'sdg17', 'mandatory', 'belgium', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
