INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a65ccbbc-7fd5-50aa-bc19-2b591288c077', 'Belgium Code Buysse III', 'Code Buysse III', 'This Code is addressed to all Belgian companies which do not fall under the definition of "listed companies" within the meaning of the Company Code. It contains recommendations on corporate governance or good corporate governance. In this regard, the interaction between the shareholders, the board of directors and the management of the company plays a key role.', 'This Code is addressed to all Belgian companies which do not fall under the definition of "listed companies" within the meaning of the Company Code. It contains recommendations on corporate governance or good corporate governance. In this regard, the interaction between the shareholders, the board of directors and the management of the company plays a key role.', 'This Code is addressed to all Belgian companies which do not fall under the definition of "listed companies" within the meaning of the Company Code. It contains recommendations on corporate governance or good corporate governance. In this regard, the interaction between the shareholders, the board of directors and the management of the company plays a key role.', 'Belgium', 'governance', 'in_force', '2017-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_6', ARRAY['sdg4', 'regulations', 'mandatory', 'belgium', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('690e6707-ce70-5b7a-93b3-885551e996e3', 'Belgium Practical Manual on Permitting and Inspection of Waste', 'Practical Manual on Permitting and Inspection of Waste Management Operations', 'The manual aims to address the waste management facilities and sites along the waste chain starting with the waste producer and ending with a certain treatment operation, including in particular WEEE collection and treatment facilities and landfills.', 'The manual aims to address the waste management facilities and sites along the waste chain starting with the waste producer and ending with a certain treatment operation, including in particular WEEE collection and treatment facilities and landfills.', 'The manual aims to address the waste management facilities and sites along the waste chain starting with the waste producer and ending with a certain treatment operation, including in particular WEEE collection and treatment facilities and landfills.', 'Belgium', 'nature', 'in_force', '2011-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_2', ARRAY['regulations', 'mandatory', 'belgium', 'sdg12', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b8790395-c90f-5be9-98ab-63fb182d004e', 'Belgium Law amending the law of March 21, 1991', 'Law amending the law of March 21, 1991 on the reform of certain economic public companies, the Companies Code and the law of April 19, 2002  […]', 'This law amends the law of March 21, 1991 on the reform of certain economic public companies, the Companies Code and the law of April 19, 2002 relating to the rationalization of the operation and management of the National Lottery in order to guarantee the presence women on the board of independent public companies, listed companies and the National Lottery.', 'This law amends the law of March 21, 1991 on the reform of certain economic public companies, the Companies Code and the law of April 19, 2002 relating to the rationalization of the operation and management of the National Lottery in order to guarantee the presence women on the board of independent public companies, listed companies and the National Lottery.', 'This law amends the law of March 21, 1991 on the reform of certain economic public companies, the Companies Code and the law of April 19, 2002 relating to the rationalization of the operation and management of the National Lottery in order to guarantee the presence women on the board of independent public companies, listed companies and the National Lottery.', 'Belgium', 'social', 'in_force', '2011-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_27', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'belgium', 'sdg5', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f491b132-ea9e-59f9-aaf2-3ca3c66e14a5', 'Belgium Law containing various provisions. German translation of extracts', 'Law containing various provisions. German translation of extracts, bl. 22700', 'The ''Law containing various provisions'' enacted in Belgium in 2010 introduced amendments to labor, social security, public procurement, and tax laws. One key requirement was for employers to provide a free German translation of employment contracts to German-speaking employees in specific regions to ensure linguistic equality and awareness of employment conditions. The law aimed to promote fairness and compliance with legal provisions, coming into force upon publication in the Belgian official gazette.', 'The ''Law containing various provisions'' enacted in Belgium in 2010 introduced amendments to labor, social security, public procurement, and tax laws. One key requirement was for employers to provide a free German translation of employment contracts to German-speaking employees in specific regions to ensure linguistic equality and awareness of employment conditions. The law aimed to promote fairness and compliance with legal provisions, coming into force upon publication in the Belgian official gazette.', 'The ''Law containing various provisions'' enacted in Belgium in 2010 introduced amendments to labor, social security, public procurement, and tax laws. One key requirement was for employers to provide a free German translation of employment contracts to German-speaking employees in specific regions to ensure linguistic equality and awareness of employment conditions. The law aimed to promote fairness and compliance with legal provisions, coming into force upon publication in the Belgian official gazette.', 'Belgium', 'social', 'in_force', '2010-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_21', ARRAY['sdg8', 'regulations', 'mandatory', 'belgium', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e0d004a2-4aa9-5cb3-929b-4c63c5995fd2', 'Belgium Laws, decrees, ordinances and ordinances', 'Laws, decrees, ordinances and ordinances', 'The "Wetten, decreten, ordonnanties en verordeningen" compilation in Belgium in 2010 covered a wide range of legal texts, including those related to business corporations. The Belgian Company Code, which governs the formation, management, and dissolution of companies in Belgium, was included in the compilation. The Code was revised in 1999 and 2006 and implemented various changes, including simplification of company formation, introduction of the simplified private limited liability company, and strengthening of minority shareholder rights. The compilation also included laws and regulations related to accounting, auditing, and financial reporting, such as the Belgian Accounting Law and the Belgian Audit Law. These laws set out the requirements for companies to prepare and publish financial statements and audits. Additionally, the compilation included laws and regulations related to corporate governance, including the Belgian Corporate Governance Code, which sets out the principles and best practices for the management of companies listed on the Belgian stock exchange. Overall, the legal framework in Belgium aimed to promote transparency, accountability, and good corporate governance practices for business corporations.', 'The "Wetten, decreten, ordonnanties en verordeningen" compilation in Belgium in 2010 covered a wide range of legal texts, including those related to business corporations. The Belgian Company Code, which governs the formation, management, and dissolution of companies in Belgium, was included in the compilation. The Code was revised in 1999 and 2006 and implemented various changes, including simplification of company formation, introduction of the simplified private limited liability company, and strengthening of minority shareholder rights. The compilation also included laws and regulations related to accounting, auditing, and financial reporting, such as the Belgian Accounting Law and the Belgian Audit Law. These laws set out the requirements for companies to prepare and publish financial statements and audits. Additionally, the compilation included laws and regulations related to corporate governance, including the Belgian Corporate Governance Code, which sets out the principles and best practices for the management of companies listed on the Belgian stock exchange. Overall, the legal framework in Belgium aimed to promote transparency, accountability, and good corporate governance practices for business corporations.', 'The "Wetten, decreten, ordonnanties en verordeningen" compilation in Belgium in 2010 covered a wide range of legal texts, including those related to business corporations. The Belgian Company Code, which governs the formation, management, and dissolution of companies in Belgium, was included in the compilation. The Code was revised in 1999 and 2006 and implemented various changes, including simplification of company formation, introduction of the simplified private limited liability company, and strengthening of minority shareholder rights. The compilation also included laws and regulations related to accounting, auditing, and financial reporting, such as the Belgian Accounting Law and the Belgian Audit Law. These laws set out the requirements for companies to prepare and publish financial statements and audits. Additionally, the compilation included laws and regulations related to corporate governance, including the Belgian Corporate Governance Code, which sets out the principles and best practices for the management of companies listed on the Belgian stock exchange. Overall, the legal framework in Belgium aimed to promote transparency, accountability, and good corporate governance practices for business corporations.', 'Belgium', 'climate', 'in_force', '2010-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_22', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'belgium', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('77778d97-0185-57f2-9f02-5317e75e2936', 'Belgium Corporate Governance Guidance and Principles for Unlisted Companies', 'Corporate Governance Guidance and Principles for Unlisted Companies in Europe', 'This document is a practical tool for unlisted companies and their stakeholders developed by the European Confederation of Directors’ Associations (ecoDa), “the European voice of board directors”.', 'This document is a practical tool for unlisted companies and their stakeholders developed by the European Confederation of Directors’ Associations (ecoDa), “the European voice of board directors”.', 'This document is a practical tool for unlisted companies and their stakeholders developed by the European Confederation of Directors’ Associations (ecoDa), “the European voice of board directors”.', 'Belgium', 'governance', 'in_force', '2010-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_29', ARRAY['guidance_frameworks', 'belgium', 'sdg16', 'disclosure', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9656a213-dfb3-5472-a74a-47d57d642c1c', 'Belgium 2009 Belgian Code on Corporate Governance', 'The 2009 Belgian Code on Corporate Governance', 'The Belgian Corporate Governance Code 2009 ("2009 Code") is primarily intended for companies governed by Belgian law, whose securities are traded on a regulated market ("listed companies"). Because of its flexibility, the 2009 Code can also serve as a reference framework for all other companies. The 2009 Code is the second edition of the Belgian Corporate Governance Code and replaces the version published in 2004. The companies have thus reviewed their corporate governance and, where necessary, adapted their corporate governance practices and their Corporate Governance Charter to the new provisions of the 2009 Code.', 'The Belgian Corporate Governance Code 2009 ("2009 Code") is primarily intended for companies governed by Belgian law, whose securities are traded on a regulated market ("listed companies"). Because of its flexibility, the 2009 Code can also serve as a reference framework for all other companies. The 2009 Code is the second edition of the Belgian Corporate Governance Code and replaces the version published in 2004. The companies have thus reviewed their corporate governance and, where necessary, adapted their corporate governance practices and their Corporate Governance Charter to the new provisions of the 2009 Code.', 'The Belgian Corporate Governance Code 2009 ("2009 Code") is primarily intended for companies governed by Belgian law, whose securities are traded on a regulated market ("listed companies"). Because of its flexibility, the 2009 Code can also serve as a reference framework for all other companies. The 2009 Code is the second edition of the Belgian Corporate Governance Code and replaces the version published in 2004. The companies have thus reviewed their corporate governance and, where necessary, adapted their corporate governance practices and their Corporate Governance Charter to the new provisions of the 2009 Code.', 'Belgium', 'governance', 'in_force', '2009-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_1', ARRAY['regulations', 'mandatory', 'belgium', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
