INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('aa2608db-ee26-50f2-b6d6-bdbb2f1e4e6f', 'Belgium Belgian Monitor of November 30, 2007 has three', 'The Belgian Monitor of November 30, 2007 has three editions, which carry the numbers 338, 339 and 340', 'The Belgian Monitor of November 30, 2007, includes various laws, decrees, and ordinances of Belgium related to sectors such as finance, public health, food chain safety, and fire services. The document outlines regulations on breeding programs for sheep, training courses for fire services, obligations of financial instrument issuers, and restrictive measures against the Taliban in Afghanistan. It also covers changes in government agencies and names of infrastructure entities.', 'The Belgian Monitor of November 30, 2007, includes various laws, decrees, and ordinances of Belgium related to sectors such as finance, public health, food chain safety, and fire services. The document outlines regulations on breeding programs for sheep, training courses for fire services, obligations of financial instrument issuers, and restrictive measures against the Taliban in Afghanistan. It also covers changes in government agencies and names of infrastructure entities.', 'The Belgian Monitor of November 30, 2007, includes various laws, decrees, and ordinances of Belgium related to sectors such as finance, public health, food chain safety, and fire services. The document outlines regulations on breeding programs for sheep, training courses for fire services, obligations of financial instrument issuers, and restrictive measures against the Taliban in Afghanistan. It also covers changes in government agencies and names of infrastructure entities.', 'Belgium', 'nature', 'in_force', '2007-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_24', ARRAY['sdg4', 'regulations', 'mandatory', 'belgium', 'sdg16', 'disclosure', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
