INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1bf9e9e0-2237-5e47-a421-e981fdd78914', 'Belgium Draft Belgian Corporate Governance Code', 'Draft Belgian Corporate Governance Code, 2004', 'The Code''s main objective is to facilitate long-term value creation and sustainable growth by proposing a good corporate governance model which should foster a balance between performance-driven direction and conformance to robust risk management systems and controls.', 'The Code''s main objective is to facilitate long-term value creation and sustainable growth by proposing a good corporate governance model which should foster a balance between performance-driven direction and conformance to robust risk management systems and controls.', 'The Code''s main objective is to facilitate long-term value creation and sustainable growth by proposing a good corporate governance model which should foster a balance between performance-driven direction and conformance to robust risk management systems and controls.', 'Belgium', 'governance', 'in_force', '2004-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_14', ARRAY['mandatory', 'belgium', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7064a3a2-1a85-5839-a144-0b3c20d5ba0f', 'Belgium Belgian Corporate Governance Code', 'Belgian Corporate Governance Code, 2004', 'This Code''s main objective is to support long-term value creation. Business success demonstrates that good governance leads to creation of wealth, not only for shareholders but also for all other stakeholders. Recent examples of corporate malpractice, however, have shown that failing corporate governance may lead to significant losses well beyond the loss of shareholder capital.', 'This Code''s main objective is to support long-term value creation. Business success demonstrates that good governance leads to creation of wealth, not only for shareholders but also for all other stakeholders. Recent examples of corporate malpractice, however, have shown that failing corporate governance may lead to significant losses well beyond the loss of shareholder capital.', 'This Code''s main objective is to support long-term value creation. Business success demonstrates that good governance leads to creation of wealth, not only for shareholders but also for all other stakeholders. Recent examples of corporate malpractice, however, have shown that failing corporate governance may lead to significant losses well beyond the loss of shareholder capital.', 'Belgium', 'climate', 'in_force', '2004-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_9', ARRAY['regulations', 'mandatory', 'belgium', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9ebb8ab1-5b8e-52da-a55d-82491bb99ebe', 'Belgium Reporting Corporate Governance', 'Reporting Corporate Governance, 1999', 'In January 1998, the Banking and Finance Commission published recommendations on the information to be disseminated by listed Belgian companies on the subject of the organization of their administration and management. These recommendations do not relate to how best to organize the management of the company, but aim to improve reporting at this level.', 'In January 1998, the Banking and Finance Commission published recommendations on the information to be disseminated by listed Belgian companies on the subject of the organization of their administration and management. These recommendations do not relate to how best to organize the management of the company, but aim to improve reporting at this level.', 'In January 1998, the Banking and Finance Commission published recommendations on the information to be disseminated by listed Belgian companies on the subject of the organization of their administration and management. These recommendations do not relate to how best to organize the management of the company, but aim to improve reporting at this level.', 'Belgium', 'climate', 'in_force', '1999-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_15', ARRAY['other sustainability policy', 'mandatory', 'belgium', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('afa103ae-0eb1-5732-87fa-902c406c9e8e', 'Belgium Judgment of June 17', 'Judgment No. 70/99 of June 17, 1999', 'This law appeals for annulment of article 131 of the law of 22 February 1998 on social provisions, inserting article 43ter in the law of 6 August 1990 relating to mutual societies and national unions of mutual societies, introduced by the National Union of Free Mutual Societies and Others.', 'This law appeals for annulment of article 131 of the law of 22 February 1998 on social provisions, inserting article 43ter in the law of 6 August 1990 relating to mutual societies and national unions of mutual societies, introduced by the National Union of Free Mutual Societies and Others.', 'This law appeals for annulment of article 131 of the law of 22 February 1998 on social provisions, inserting article 43ter in the law of 6 August 1990 relating to mutual societies and national unions of mutual societies, introduced by the National Union of Free Mutual Societies and Others.', 'Belgium', 'governance', 'in_force', '1999-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_23', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'belgium', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('76c8ba55-bd1f-5fe8-a19c-57ba3505e458', 'Belgium Corporate Governance - Recommendations', 'Corporate Governance - Recommendations, 1998', 'This document concerns the VBO/FEB ratified recommendations for the  administration and management of companies in order to meet the expectations of shareholders and the requirements of the economic process.', 'This document concerns the VBO/FEB ratified recommendations for the  administration and management of companies in order to meet the expectations of shareholders and the requirements of the economic process.', 'This document concerns the VBO/FEB ratified recommendations for the  administration and management of companies in order to meet the expectations of shareholders and the requirements of the economic process.', 'Belgium', 'governance', 'in_force', '1998-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_12', ARRAY['guidance_frameworks', 'belgium', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a89febca-e9d5-5457-b739-a4713c01e608', 'Belgium Corporate Governance for Belgian Listed Companies (The Cardon', 'Corporate Governance for Belgian Listed Companies (The Cardon Report) 1998', 'The recommendations serve a double purpose: on the one hand, they aim to provide listed companies with a framework in which they can consider their corporate governance and on the other hand they aim to enhance the understanding of the situation of Belgian listed companies by the international investors'' community.', 'The recommendations serve a double purpose: on the one hand, they aim to provide listed companies with a framework in which they can consider their corporate governance and on the other hand they aim to enhance the understanding of the situation of Belgian listed companies by the international investors'' community.', 'The recommendations serve a double purpose: on the one hand, they aim to provide listed companies with a framework in which they can consider their corporate governance and on the other hand they aim to enhance the understanding of the situation of Belgian listed companies by the international investors'' community.', 'Belgium', 'climate', 'in_force', '1998-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_13', ARRAY['other sustainability policy', 'sdg11', 'mandatory', 'belgium', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a9c3da21-ce16-51af-8f9b-965c22ad6231', 'Belgium Royal Decree of August 4, 1996 Relating', 'Royal Decree of August 4, 1996 Relating to the Social Report', 'In 1996, the Belgian government issued the "Arrêté royal relatif au bilan social" (Royal Decree on Social Balance Sheet) to require certain companies to report on their social and environmental impacts. The decree aimed to increase transparency and accountability for companies operating in Belgium. Specifically, it required large companies to report on a range of social and environmental issues, including employment practices, health and safety, environmental impact, and community engagement. The social balance sheet was meant to be published alongside the company''s annual financial statements. The decree applied to companies with more than 100 employees or a turnover exceeding a certain threshold. The aim of the social balance sheet was to encourage companies to adopt more responsible business practices and contribute to the well-being of society and the environment.', 'In 1996, the Belgian government issued the "Arrêté royal relatif au bilan social" (Royal Decree on Social Balance Sheet) to require certain companies to report on their social and environmental impacts. The decree aimed to increase transparency and accountability for companies operating in Belgium. Specifically, it required large companies to report on a range of social and environmental issues, including employment practices, health and safety, environmental impact, and community engagement. The social balance sheet was meant to be published alongside the company''s annual financial statements. The decree applied to companies with more than 100 employees or a turnover exceeding a certain threshold. The aim of the social balance sheet was to encourage companies to adopt more responsible business practices and contribute to the well-being of society and the environment.', 'In 1996, the Belgian government issued the "Arrêté royal relatif au bilan social" (Royal Decree on Social Balance Sheet) to require certain companies to report on their social and environmental impacts. The decree aimed to increase transparency and accountability for companies operating in Belgium. Specifically, it required large companies to report on a range of social and environmental issues, including employment practices, health and safety, environmental impact, and community engagement. The social balance sheet was meant to be published alongside the company''s annual financial statements. The decree applied to companies with more than 100 employees or a turnover exceeding a certain threshold. The aim of the social balance sheet was to encourage companies to adopt more responsible business practices and contribute to the well-being of society and the environment.', 'Belgium', 'climate', 'in_force', '1996-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_19', ARRAY['sdg8', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'belgium', 'sdg16', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2daab7ad-2670-57b3-9375-8c0fd4e05576', 'Belgium Income Tax Code', 'Income Tax Code 1992', 'The Income Tax Code 1992 in Belgium outlines regulations for various income sources, deductions, and tax calculations, targeting individuals and entities subject to income tax. It specifies taxable and exempt income, allowable deductions, and tax rates, serving as a guide for tax compliance and assessment.', 'The Income Tax Code 1992 in Belgium outlines regulations for various income sources, deductions, and tax calculations, targeting individuals and entities subject to income tax. It specifies taxable and exempt income, allowable deductions, and tax rates, serving as a guide for tax compliance and assessment.', 'The Income Tax Code 1992 in Belgium outlines regulations for various income sources, deductions, and tax calculations, targeting individuals and entities subject to income tax. It specifies taxable and exempt income, allowable deductions, and tax rates, serving as a guide for tax compliance and assessment.', 'Belgium', 'governance', 'in_force', '1992-01-01'::date, 'Belgium', 'https://www.carrotsandsticks.org/policies/16_36', ARRAY['mandatory', 'belgium', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7346ceda-8dcd-5456-b5d0-10a32228032e', 'Bhutan Second Nationally Determined Contribution', 'Second Nationally Determined Contribution', 'In presenting the second NDC, Bhutan maintains the commitment to remain carbon-neutral where emission of greenhouse gases will not exceed carbon sequestration by our forests and sinks as first pledged in 2009 and reaffirmed in the first NDC.', 'In presenting the second NDC, Bhutan maintains the commitment to remain carbon-neutral where emission of greenhouse gases will not exceed carbon sequestration by our forests and sinks as first pledged in 2009 and reaffirmed in the first NDC.', 'In presenting the second NDC, Bhutan maintains the commitment to remain carbon-neutral where emission of greenhouse gases will not exceed carbon sequestration by our forests and sinks as first pledged in 2009 and reaffirmed in the first NDC.', 'Bhutan', 'climate', 'in_force', '2021-01-01'::date, 'Bhutan', 'https://www.carrotsandsticks.org/policies/18_2', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'sdg7', 'sdg11', 'mandatory', 'mandatory_regulations', 'bhutan', 'sdg12', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3f7cc7bd-3017-5eeb-afaf-598cbc622294', 'Bhutan Communication of INDC', 'Communication of INDC of the Kingdom of Bhutan', 'Bhutan intends to remain carbon neutral where emission of greenhouse gases will not exceed carbon sequestration by our forests, which is estimated at 6.3 million tons of CO2. Bhutan will maintain a minimum of 60 percent of total land under forest cover for all time in accordance the Constitution of the Kingdom of Bhutan. Efforts will also be made to maintain current levels of forest cover, which currently stand at 70.46%, through sustainable forest management and conservation of environmental services.', 'Bhutan intends to remain carbon neutral where emission of greenhouse gases will not exceed carbon sequestration by our forests, which is estimated at 6.3 million tons of CO2. Bhutan will maintain a minimum of 60 percent of total land under forest cover for all time in accordance the Constitution of the Kingdom of Bhutan. Efforts will also be made to maintain current levels of forest cover, which currently stand at 70.46%, through sustainable forest management and conservation of environmental services.', 'Bhutan intends to remain carbon neutral where emission of greenhouse gases will not exceed carbon sequestration by our forests, which is estimated at 6.3 million tons of CO2. Bhutan will maintain a minimum of 60 percent of total land under forest cover for all time in accordance the Constitution of the Kingdom of Bhutan. Efforts will also be made to maintain current levels of forest cover, which currently stand at 70.46%, through sustainable forest management and conservation of environmental services.', 'Bhutan', 'climate', 'in_force', '2015-01-01'::date, 'Bhutan', 'https://www.carrotsandsticks.org/policies/18_1', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'sdg7', 'sdg11', 'mandatory', 'mandatory_regulations', 'bhutan', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c887f2dc-ed6c-55ae-9b07-9e6c10b5eaf6', 'Bolivia Title XI Corporate Social Responsibility Management', 'Title XI Corporate Social Responsibility Management', 'The purpose of this Regulation is to establish provisions that Financial Intermediation Entities must comply with in relation to Corporate Social Responsibility (CSR).', 'The purpose of this Regulation is to establish provisions that Financial Intermediation Entities must comply with in relation to Corporate Social Responsibility (CSR).', 'The purpose of this Regulation is to establish provisions that Financial Intermediation Entities must comply with in relation to Corporate Social Responsibility (CSR).', 'Bolivia', 'governance', 'in_force', '2015-01-01'::date, 'Bolivia', 'https://www.carrotsandsticks.org/policies/19_1', ARRAY['disclosure', 'bolivia', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5d6ff3a9-cca3-5dee-afc6-115b358fe3a3', 'Bolivia Supreme Decree', 'Supreme Decree No. 2936 2014', 'The purpose of this Supreme Decree is to regulate Law No. 545, of July 14, 2014, which ratifies Convention No. 167 "Convention on Safety and Health in Construction", of the International Labor Organization - ILO.', 'The purpose of this Supreme Decree is to regulate Law No. 545, of July 14, 2014, which ratifies Convention No. 167 "Convention on Safety and Health in Construction", of the International Labor Organization - ILO.', 'The purpose of this Supreme Decree is to regulate Law No. 545, of July 14, 2014, which ratifies Convention No. 167 "Convention on Safety and Health in Construction", of the International Labor Organization - ILO.', 'Bolivia', 'governance', 'in_force', '2014-01-01'::date, 'Bolivia', 'https://www.carrotsandsticks.org/policies/19_26', ARRAY['other sustainability policy', 'bolivia', 'regulations', 'mandatory', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6d501d41-885f-5c7a-b924-ec6a48485e67', 'Bolivia Financial Services', 'Law No. 393 on Financial Services', 'The purpose of this Law is to regulate financial intermediation activities and the provision of financial services, as well as the organization and operation of financial entities and providers of financial services; financial consumer protection; and the participation of the State as rector of the financial system, ensuring the universality of financial services and directing their operation in support of the economic and social development policies of the country.', 'The purpose of this Law is to regulate financial intermediation activities and the provision of financial services, as well as the organization and operation of financial entities and providers of financial services; financial consumer protection; and the participation of the State as rector of the financial system, ensuring the universality of financial services and directing their operation in support of the economic and social development policies of the country.', 'The purpose of this Law is to regulate financial intermediation activities and the provision of financial services, as well as the organization and operation of financial entities and providers of financial services; financial consumer protection; and the participation of the State as rector of the financial system, ensuring the universality of financial services and directing their operation in support of the economic and social development policies of the country.', 'Bolivia', 'climate', 'in_force', '2013-01-01'::date, 'Bolivia', 'https://www.carrotsandsticks.org/policies/19_2', ARRAY['disclosure', 'bolivia', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6478a6d8-3f84-5bb2-b716-0854e56819c2', 'Bolivia Recommendations on Good Beekeeping Practices and Good Manufacturing', 'Recommendations on Good Beekeeping Practices and Good Manufacturing Practices', 'This document is aimed at the leaders of the associations of beekeepers, in their capacity as responsible for the proper functioning of the associations, the staff of these associations and the partners who are the beekeepers. honey suppliers of their organizations.', 'This document is aimed at the leaders of the associations of beekeepers, in their capacity as responsible for the proper functioning of the associations, the staff of these associations and the partners who are the beekeepers. honey suppliers of their organizations.', 'This document is aimed at the leaders of the associations of beekeepers, in their capacity as responsible for the proper functioning of the associations, the staff of these associations and the partners who are the beekeepers. honey suppliers of their organizations.', 'Bolivia', 'nature', 'in_force', '2012-01-01'::date, 'Bolivia', 'https://www.carrotsandsticks.org/policies/19_16', ARRAY['sdg2', 'other sustainability policy', 'bolivia', 'regulations', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9f9e7f65-5efc-5906-9af2-934354de82a2', 'Official Gazette of the Plurinational State of Bolivia', 'Official Gazette of the Plurinational State of Bolivia Supreme Decree No. 1486 Evo Morales Ayma Constitutional President of the Plurinational State of Bolivia', 'That Paragraph I of Article 15 of the Political Constitution of the State, determines that every person has the right to life and physical, psychological and sexual integrity. No one will be tortured or suffer cruel, inhuman, degrading or humiliating treatment.', 'That Paragraph I of Article 15 of the Political Constitution of the State, determines that every person has the right to life and physical, psychological and sexual integrity. No one will be tortured or suffer cruel, inhuman, degrading or humiliating treatment.', 'That Paragraph I of Article 15 of the Political Constitution of the State, determines that every person has the right to life and physical, psychological and sexual integrity. No one will be tortured or suffer cruel, inhuman, degrading or humiliating treatment.', 'Bolivia', 'governance', 'in_force', '2012-01-01'::date, 'Bolivia', 'https://www.carrotsandsticks.org/policies/19_20', ARRAY['bolivia', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a204cf31-75e5-5eb1-9b9a-1a546e901c4e', 'Bolivia Law , December 21', 'Law No. 71, December 21, 2010', 'The purpose of this Law is to recognize the rights of Mother Earth, as well as the obligations and duties of the Plurinational State and society to guarantee respect for these rights.', 'The purpose of this Law is to recognize the rights of Mother Earth, as well as the obligations and duties of the Plurinational State and society to guarantee respect for these rights.', 'The purpose of this Law is to recognize the rights of Mother Earth, as well as the obligations and duties of the Plurinational State and society to guarantee respect for these rights.', 'Bolivia', 'climate', 'in_force', '2010-01-01'::date, 'Bolivia', 'https://www.carrotsandsticks.org/policies/19_13', ARRAY['sdg13', 'other sustainability policy', 'bolivia', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('68731bcc-4dc5-57da-84a9-5aee5e7a8047', 'Bolivia Environmental Regulation for the Manufacturing Industrial Sector', 'Environmental Regulation for the Manufacturing Industrial Sector', 'Within the framework of Law 1333 on the Environment, this sectoral Regulation is intended to regulate the activities of the Industrial Manufacturing Sector.', 'Within the framework of Law 1333 on the Environment, this sectoral Regulation is intended to regulate the activities of the Industrial Manufacturing Sector.', 'Within the framework of Law 1333 on the Environment, this sectoral Regulation is intended to regulate the activities of the Industrial Manufacturing Sector.', 'Bolivia', 'governance', 'in_force', '2002-01-01'::date, 'Bolivia', 'https://www.carrotsandsticks.org/policies/19_25', ARRAY['other sustainability policy', 'bolivia', 'regulations', 'mandatory', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ce880006-8b4f-5b11-ab9c-8205c0940341', 'Bolivia Law Mining Code of March 17', 'Law No. 1777 Mining Code of March 17, 1997', 'The Ley no. 1777 código de minería del 17 de marzo de 1997 is the Mining Code of Bolivia, which was enacted in 1997. The code sets out the legal framework for the exploration, exploitation, and commercialization of mining resources in Bolivia. The code also regulates the rights and obligations of mining companies, including the procedures for obtaining mining licenses, mining concessions, and environmental permits. The code also outlines the responsibilities of mining companies with respect to labor relations, safety, and environmental protection. The Mining Code of Bolivia was introduced to promote the sustainable development of the mining sector and to ensure that mining activities are conducted in a responsible and environmentally friendly manner.', 'The Ley no. 1777 código de minería del 17 de marzo de 1997 is the Mining Code of Bolivia, which was enacted in 1997. The code sets out the legal framework for the exploration, exploitation, and commercialization of mining resources in Bolivia. The code also regulates the rights and obligations of mining companies, including the procedures for obtaining mining licenses, mining concessions, and environmental permits. The code also outlines the responsibilities of mining companies with respect to labor relations, safety, and environmental protection. The Mining Code of Bolivia was introduced to promote the sustainable development of the mining sector and to ensure that mining activities are conducted in a responsible and environmentally friendly manner.', 'The Ley no. 1777 código de minería del 17 de marzo de 1997 is the Mining Code of Bolivia, which was enacted in 1997. The code sets out the legal framework for the exploration, exploitation, and commercialization of mining resources in Bolivia. The code also regulates the rights and obligations of mining companies, including the procedures for obtaining mining licenses, mining concessions, and environmental permits. The code also outlines the responsibilities of mining companies with respect to labor relations, safety, and environmental protection. The Mining Code of Bolivia was introduced to promote the sustainable development of the mining sector and to ensure that mining activities are conducted in a responsible and environmentally friendly manner.', 'Bolivia', 'climate', 'in_force', '1997-01-01'::date, 'Bolivia', 'https://www.carrotsandsticks.org/policies/19_10', ARRAY['sdg13', 'other sustainability policy', 'bolivia', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9fc5ba06-3dd6-50e9-a133-b0e40ba65b19', 'Bolivia Environmental Regulation for Mining Activities, July 31', 'Environmental Regulation for Mining Activities, July 31, 1997', 'Environmental management in mining is a set of actions and processes for the protection of the environment from the start to the conclusion of a mining activity. Environmental management in the company must be defined at the highest level of decision, integrated into the production plans and be known to all staff.', 'Environmental management in mining is a set of actions and processes for the protection of the environment from the start to the conclusion of a mining activity. Environmental management in the company must be defined at the highest level of decision, integrated into the production plans and be known to all staff.', 'Environmental management in mining is a set of actions and processes for the protection of the environment from the start to the conclusion of a mining activity. Environmental management in the company must be defined at the highest level of decision, integrated into the production plans and be known to all staff.', 'Bolivia', 'climate', 'in_force', '1997-01-01'::date, 'Bolivia', 'https://www.carrotsandsticks.org/policies/19_24', ARRAY['other sustainability policy', 'bolivia', 'regulations', 'mandatory', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
